// Frozen-analysis preparation. Input order/journal certification is a separate
// obligation; this program never promotes its numerical output to admitted data.
#include <gmpxx.h>
#include <algorithm>
#include <cmath>
#include <filesystem>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <map>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>
namespace fs=std::filesystem;
static void need(bool b,const std::string& s){if(!b)throw std::runtime_error(s);}
static std::vector<std::string> split(const std::string& s){std::istringstream f(s);std::string x;std::vector<std::string> v;while(std::getline(f,x,'\t'))v.push_back(x);return v;}
static unsigned long number(const std::string& s){size_t used=0;need(!s.empty()&&s[0]!='-',"unsigned input");auto n=std::stoul(s,&used);need(used==s.size(),"unsigned trailing bytes");return n;}
static mpz_class integer(const std::string& s){mpz_class n;need(n.set_str(s,0)==0,"integer");return n;}
static bool prime(int x){if(x<2)return false;for(int d=2;d<=x/d;++d)if(x%d==0)return false;return true;}
static int strict_count(const mpz_class& p,const mpz_class& n){mpz_class t=p+1-n,d=t*t-4*p;need(d<0,"Hasse discriminant");int count=0;for(int l=3;l<=691;l+=2)if(prime(l)){mpz_class q=l,a,e=(l-1)/2,r;mpz_mod(a.get_mpz_t(),d.get_mpz_t(),q.get_mpz_t());mpz_powm(r.get_mpz_t(),a.get_mpz_t(),e.get_mpz_t(),q.get_mpz_t());count+=r==1;}return count;}
// Sum from the mode of the truncated binomial mass, avoiding tail underflow.
static long double cdf(int n,int k,long double p){if(k<0)return 0;if(k>=n)return 1;if(p<=0)return 1;if(p>=1)return 0;int mode=std::min(k,static_cast<int>(std::floor((n+1)*p)));long double logmass=std::lgamma(static_cast<long double>(n)+1)-std::lgamma(static_cast<long double>(mode)+1)-std::lgamma(static_cast<long double>(n-mode)+1)+mode*std::log(p)+(n-mode)*std::log1p(-p);long double sum=1,term=1;for(int j=mode;j>0;--j){term*=static_cast<long double>(j)/(n-j+1)*(1-p)/p;sum+=term;}term=1;for(int j=mode;j<k;++j){term*=static_cast<long double>(n-j)/(j+1)*p/(1-p);sum+=term;}return std::min(1.0L,std::max(0.0L,std::exp(logmass)*sum));}
static long double inverse_cdf_p(int n,int k,long double target){long double lo=0,hi=1;for(int i=0;i<80;++i){long double mid=(lo+hi)/2;if(cdf(n,k,mid)>target)lo=mid;else hi=mid;}return (lo+hi)/2;}
static std::pair<long double,long double> cp95(int n,int k){need(n>0&&k>=0&&k<=n,"binomial counts");return {k==0?0:inverse_cdf_p(n,k-1,0.975L),k==n?1:inverse_cdf_p(n,k,0.025L)};}
static std::vector<long double> holm(const std::vector<long double>& p){std::vector<size_t> order(p.size());for(size_t i=0;i<p.size();++i)order[i]=i;std::stable_sort(order.begin(),order.end(),[&](size_t a,size_t b){return p[a]<p[b];});std::vector<long double> out(p.size());long double prev=0;for(size_t j=0;j<order.size();++j){prev=std::max(prev,std::min(1.0L,(order.size()-j)*p[order[j]]));out[order[j]]=prev;}return out;}
struct Rank{int lt=0,eq=0,le=0;};
static Rank rank_of(const std::vector<int>& sample,int target){Rank r;for(int n:sample){r.lt+=n<target;r.eq+=n==target;}r.le=r.lt+r.eq;return r;}
static void selftest(){need(std::abs(cdf(4,1,.5L)-.3125L)<1e-15L,"binomial CDF fixture");auto a=cp95(1,0),b=cp95(1,1);need(a.first==0&&std::abs(a.second-.975L)<1e-12L&&std::abs(b.first-.025L)<1e-12L&&b.second==1,"Clopper-Pearson boundary fixtures");auto r=rank_of({1,2,2,4},2);need(r.lt==1&&r.eq==2&&r.le==3,"tied percentile fixture");auto h=holm({.001L,.04L,.07L});need(std::abs(h[0]-.003L)<1e-12L&&std::abs(h[1]-.08L)<1e-12L&&std::abs(h[2]-.08L)<1e-12L,"Holm fixture");auto m=cp95(10000,5000);need(m.first<.5L&&m.second>.5L&&std::abs(m.first+m.second-1)<1e-10L,"central binomial symmetry");need(strict_count(mpz_class(101),mpz_class(101))>=0,"Euler-symbol path");std::cout<<"PASS:ties,binomial CDF,Clopper-Pearson boundaries/10k symmetry,Holm and Euler-symbol path\n";}
struct Target{std::string id;int bits,score;};
int main(int argc,char** argv){try{if(argc==2&&std::string(argv[1])=="--self-test"){selftest();return 0;}need(argc==5&&std::string(argv[4])=="ACK_FROZEN_CHECKPOINT","percentiles COHORT JOURNAL_ROOT FRESH_OUTPUT ACK_FROZEN_CHECKPOINT");std::ifstream f(argv[1]);need(bool(f),"cohort");std::map<int,mpz_class> ps;std::vector<Target> targets;std::string line;int row_count=0;while(std::getline(f,line)){if(line.empty()||line[0]=='#')continue;auto c=split(line);need(c.size()==9,"cohort width");++row_count;int bits=static_cast<int>(number(c[1]));mpz_class p=integer(c[5]),n=integer(c[7]);if(ps.count(bits))need(ps.at(bits)==p,"unique fixed field");else ps.emplace(bits,p);need(c[2]=="published"||c[2]=="skipped","role");if(c[2]=="published")targets.push_back({c[0],bits,strict_count(p,n)});}need(row_count==21&&targets.size()==10&&ps.size()==6,"fixed input inventory");std::map<int,std::vector<int>> samples;for(const auto& field:ps){fs::path path=fs::path(argv[2])/std::to_string(field.first)/"accepted.tsv";std::ifstream a(path);need(bool(a),"missing full field baseline "+path.string());need(bool(std::getline(a,line))&&line=="bits\tordinal\tindex\tseed\tc\tb\tn\tGx\tGy\tstrict691\tramified691","accepted header");unsigned long previous=0;auto& sample=samples[field.first];while(std::getline(a,line)){auto c=split(line);need(c.size()==11,"accepted columns");need(number(c[0])==static_cast<unsigned long>(field.first)&&number(c[1])==sample.size()+1,"field/ordinal");unsigned long index=number(c[2]);need(sample.empty()||index>previous,"strict attempt ordering");previous=index;mpz_class n=integer(c[6]);int score=strict_count(field.second,n);need(number(c[9])==static_cast<unsigned long>(score),"independent Euler count recomputation");sample.push_back(score);}need(sample.size()==10000,"exactly10000accepted per field; no smaller replacement");}
 std::vector<long double> probabilities;std::vector<Rank> ranks;for(const auto& t:targets){auto r=rank_of(samples.at(t.bits),t.score);ranks.push_back(r);probabilities.push_back((1.0L+r.le)/10001.0L);}auto corrected=holm(probabilities);fs::path out=argv[3];need(!fs::exists(out),"fresh output");fs::create_directories(out);std::ofstream table(out/"percentiles.tsv"),summary(out/"summary.json");need(bool(table)&&bool(summary),"outputs");table<<std::setprecision(16)<<"label\tbits\tstrict691\tN\tk_lt\tk_eq\tk_le\tpercentile_lt\tpercentile_le\tmidrank\tF_lt_ci95_low\tF_lt_ci95_high\tF_le_ci95_low\tF_le_ci95_high\tlower_tail_add_one\tholm10\tlower_decile\tholm_significant\n";for(size_t i=0;i<targets.size();++i){const auto& t=targets[i];auto r=ranks[i];auto lo=cp95(10000,r.lt),hi=cp95(10000,r.le);table<<t.id<<'\t'<<t.bits<<'\t'<<t.score<<"\t10000\t"<<r.lt<<'\t'<<r.eq<<'\t'<<r.le<<'\t'<<r.lt/10000.0L<<'\t'<<r.le/10000.0L<<'\t'<<(r.lt+r.le)/20000.0L<<'\t'<<lo.first<<'\t'<<lo.second<<'\t'<<hi.first<<'\t'<<hi.second<<'\t'<<probabilities[i]<<'\t'<<corrected[i]<<'\t'<<(r.le<=1000)<<'\t'<<(corrected[i]<=.05L)<<'\n';}summary<<"{\"kind\":\"fixed691-primary-percentiles/v1\",\"accepted_per_field\":10000,\"fields\":6,\"targets\":10,\"cutoff\":691,\"direction\":\"lower\",\"seed_model\":\"pseudorandom IID uniform160 assumption\",\"multiplicity\":\"Holm10 alpha0.05\",\"marginal_interval\":\"Clopper-Pearson numerical inversion\",\"independent_full_journal_verification_pending\":true,\"historical_use_established\":false,\"security_advantage_established\":false}\n";need(bool(table)&&bool(summary),"writes");std::cout<<"Computed all10 primary percentile summaries; full-journal admission remains separate\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
